data class Item(val name: String, val units: Int)

fun restockNeeded(items: List<Item>, threshold: Int): List<String> =
    items.filter { it.units < threshold }
        .map { it.name }
        .sorted()

fun main() {
    val items = listOf(Item("bolts", 2), Item("nuts", 9), Item("washers", 1))
    println(restockNeeded(items, 3))
}
